<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Http\Request;
class AdminPermissionMiddleware{public function handle(Request $request,Closure $next){$user=$request->user();abort_unless($user,403);$permission=$this->permissionFor((string)optional($request->route())->getName());if($permission&&!$user->hasPermission($permission))abort(403,'شما اجازه دسترسی به این بخش را ندارید.');return $next($request);}private function permissionFor(string $route):?string{$map=['admin.users'=>'users.manage','admin.roles'=>'permissions.manage','admin.categories'=>'products.categories','admin.products.approvals'=>'products.approve','admin.products'=>'products.manage','admin.content'=>'content.manage','admin.blog'=>'content.blog','admin.support'=>'support.manage','admin.ai'=>'ai.manage','admin.storage'=>'storage.manage','admin.discounts'=>'marketing.discounts','admin.wallets'=>'finance.wallets','admin.module.users'=>'users.manage','admin.module.products'=>'products.manage','admin.module.orders'=>'orders.manage','admin.module.finance'=>'finance.manage','admin.module.subscriptions'=>'subscriptions.manage','admin.module.assets'=>'assets.manage','admin.module.reader'=>'reader.manage','admin.module.loyalty'=>'loyalty.manage','admin.module.content'=>'content.manage','admin.module.marketing'=>'marketing.manage','admin.module.ai'=>'ai.manage','admin.module.support'=>'support.manage','admin.module.notifications'=>'notifications.manage','admin.module.reports'=>'reports.manage','admin.module.storage'=>'storage.manage','admin.module.search'=>'search.manage','admin.module.sellers'=>'sellers.manage','admin.module.workflow'=>'workflow.manage','admin.module.tasks'=>'tasks.manage','admin.module.security'=>'security.manage','admin.module.integrations'=>'integrations.manage','admin.module.settings'=>'settings.manage','admin.module.system'=>'system.manage','admin.module.developer'=>'developer.manage','admin.module.newsletter'=>'newsletter.manage','admin.module.sms'=>'sms.manage','admin.settings'=>'settings.manage','admin.dashboard'=>'dashboard.view'];foreach($map as $prefix=>$permission)if($route===$prefix||str_starts_with($route,$prefix.'.'))return $permission;return 'admin.modules';}}
